package alternate;public class QueueCore<E>{private E[]data;private int head,size;public QueueCore(E[]storage){data=storage;}<U extends E> void put(U value){if(size==data.length){E[]grown=java.util.Arrays.copyOf(data,data.length*3);for(int i=0;i<size;i++)grown[i]=data[(head+i)%data.length];data=grown;head=0;}data[(head+size++)%data.length]=value;}E get(){if(size==0){System.out.println("empty");return null;}E value=data[head];head=(head+1)%data.length;size--;return value;}}
